1	// docs/orchestration/DASHBOARD_DESIGN.md의 API 계약과 일치하는 타입·fetch.
2	
3	const BASE = import.meta.env.VITE_API_BASE ?? "";
4	
5	export interface Stats {
6	  total_findings: number;
7	  total_cards: number;
8	  review: { accepted: number; rejected: number; pending: number };
9	  acceptance_rate: number | null;
10	  by_principle: { principle: string; count: number }[];
11	  by_severity: { severity: number; count: number }[];
12	  cards_over_time: { date: string; count: number }[];
13	}
14	
15	export interface Finding {
16	  id: number;
17	  session_id: string;
18	  class_name: string;
19	  metric: string;
20	  value: number;
21	  threshold: number;
22	  principle: string;
23	  severity: number;
24	  created_at: string;
25	}
26	
27	export interface CardSummary {
28	  id: string;
29	  principle: string;
30	  severity: number;
31	  violation_reason: string;
32	  user_accepted: boolean | null;
33	  generated_at: string;
34	  reviewed_at: string | null;
35	}
36	
37	export interface CardDetail extends CardSummary {
38	  session_id: string;
39	  finding_id: number;
40	  code_hash: string;
41	  cost_example: string;
42	  before_code: string;
43	  after_code: string;
44	  learning_points: string[];
45	  revision_prompt: string;
46	  user_feedback: string | null;
47	}
48	
49	async function get<T>(path: string): Promise<T> {
50	  const res = await fetch(`${BASE}${path}`);
51	  if (!res.ok) throw new Error(`${path}: ${res.status}`);
52	  return res.json() as Promise<T>;
53	}
54	
55	export const api = {
56	  stats: () => get<Stats>("/api/stats"),
57	  findings: () => get<Finding[]>("/api/findings"),
58	  cards: (status = "all") => get<CardSummary[]>(`/api/cards?status=${status}`),
59	  card: (id: string) => get<CardDetail>(`/api/cards/${id}`),
60	};
