1	import { useEffect, useState } from "react";
2	
3	interface State<T> {
4	  data: T | null;
5	  error: string | null;
6	  loading: boolean;
7	}
8	
9	// 단순 read fetch 훅. deps가 바뀌면 다시 부른다.
10	export function useFetch<T>(fn: () => Promise<T>, deps: unknown[] = []): State<T> {
11	  const [state, setState] = useState<State<T>>({
12	    data: null,
13	    error: null,
14	    loading: true,
15	  });
16	
17	  useEffect(() => {
18	    let alive = true;
19	    setState({ data: null, error: null, loading: true });
20	    fn()
21	      .then((data) => alive && setState({ data, error: null, loading: false }))
22	      .catch((e) => alive && setState({ data: null, error: String(e), loading: false }));
23	    return () => {
24	      alive = false;
25	    };
26	    // eslint-disable-next-line react-hooks/exhaustive-deps
27	  }, deps);
28	
29	  return state;
30	}
