1	import { useState } from "react";
2	import { api, type CardDetail, type CardSummary } from "../api";
3	import { useFetch } from "../useFetch";
4	
5	const STATUSES = [
6	  { key: "all", label: "전체" },
7	  { key: "pending", label: "검수 대기" },
8	  { key: "accepted", label: "채택" },
9	  { key: "rejected", label: "거절" },
10	];
11	
12	function reviewBadge(accepted: boolean | null) {
13	  if (accepted === null) return <span className="badge pending">검수 대기</span>;
14	  if (accepted) return <span className="badge accepted">채택</span>;
15	  return <span className="badge rejected">거절</span>;
16	}
17	
18	function CardModal({ id, onClose }: { id: string; onClose: () => void }) {
19	  const { data, error, loading } = useFetch<CardDetail>(() => api.card(id), [id]);
20	
21	  return (
22	    <div className="modal-backdrop" onClick={onClose}>
23	      <div className="modal" onClick={(e) => e.stopPropagation()}>
24	        <button className="modal-close" onClick={onClose}>
25	          ✕
26	        </button>
27	        {loading && <p className="muted">불러오는 중...</p>}
28	        {error && <p className="error">{error}</p>}
29	        {data && (
30	          <>
31	            <h2>
32	              {data.id} · {data.principle} · 심각도 {data.severity}/10{" "}
33	              {reviewBadge(data.user_accepted)}
34	            </h2>
35	            <h4>위반 이유</h4>
36	            <p>{data.violation_reason}</p>
37	            <h4>운영 단계 비용</h4>
38	            <p>{data.cost_example}</p>
39	            <div className="code-cols">
40	              <div>
41	                <h4>Before</h4>
42	                <pre>{data.before_code}</pre>
43	              </div>
44	              <div>
45	                <h4>After</h4>
46	                <pre>{data.after_code}</pre>
47	              </div>
48	            </div>
49	            <h4>학습 포인트</h4>
50	            <ul>
51	              {data.learning_points.map((p, i) => (
52	                <li key={i}>{p}</li>
53	              ))}
54	            </ul>
55	            <h4>재요청 prompt</h4>
56	            <pre className="prompt">{data.revision_prompt}</pre>
57	            {data.user_feedback && (
58	              <>
59	                <h4>거절 사유</h4>
60	                <p className="muted">{data.user_feedback}</p>
61	              </>
62	            )}
63	          </>
64	        )}
65	      </div>
66	    </div>
67	  );
68	}
