70	export default function Cards() {
71	  const [status, setStatus] = useState("all");
72	  const [openId, setOpenId] = useState<string | null>(null);
73	  const { data, error, loading } = useFetch<CardSummary[]>(
74	    () => api.cards(status),
75	    [status],
76	  );
77	
78	  return (
79	    <div>
80	      <div className="filter-row">
81	        {STATUSES.map((s) => (
82	          <button
83	            key={s.key}
84	            className={`filter ${status === s.key ? "active" : ""}`}
85	            onClick={() => setStatus(s.key)}
86	          >
87	            {s.label}
88	          </button>
89	        ))}
90	      </div>
91	
92	      {loading && <p className="muted">불러오는 중...</p>}
93	      {error && <p className="error">API 연결 실패: {error}</p>}
94	      {data && data.length === 0 && <p className="muted">해당 카드가 없다.</p>}
95	
96	      <div className="card-grid">
97	        {data?.map((c) => (
98	          <button key={c.id} className="learning-card" onClick={() => setOpenId(c.id)}>
99	            <div className="learning-card-head">
100	              <span className="mono">{c.id}</span>
101	              {reviewBadge(c.user_accepted)}
102	            </div>
103	            <div className="learning-card-principle">{c.principle}</div>
104	            <p className="learning-card-reason">{c.violation_reason}</p>
105	            <div className="muted small">심각도 {c.severity}/10</div>
106	          </button>
107	        ))}
108	      </div>
109	
110	      {openId && <CardModal id={openId} onClose={() => setOpenId(null)} />}
111	    </div>
112	  );
113	}
